Here is the source code:
<source_code>
import java.io.*; 
import java.text.*; 
import java.util.*; 
import java.math.*;
public class C { 
    public static void main(String[] args) throws Exception {
        new C().run();
    } 
    public void run() throws Exception { 
        FastScanner f = new FastScanner(); 
        PrintWriter out = new PrintWriter(System.out); 
        int n = f.nextInt();
        double p = f.nextDouble();

        // Handle edge case: if p is 0, answer is 0
        if (p == 0) {
            out.println(0);
            out.flush();
            return;
        }

        // Try each possible number of maps to study (from 0 to n)
        for(int i = 0; i <= n; i++) {
            double prob = calculateProbability(i, n);
            if(prob + 1e-12 >= p) {
                out.println(i);
                break;
            }
        }

        out.flush();
    }

    private double calculateProbability(int studied, int total) {
        if (studied == 0) return 0.0;

        // Total ways to choose 3 maps from n
        long totalWays = (long)total * (total-1) * (total-2);

        // Count favorable outcomes
        long favorable = 0;

        // Case 1: All 3 maps are studied
        if (studied >= 3) {
            favorable += (long)studied * (studied-1) * (studied-2);
        }

        // Case 2: Exactly 2 maps are studied
        if (studied >= 2 && (total - studied) >= 1) {
            // Number of ways: C(studied, 2) * C(total-studied, 1) * 2
            // The factor 2 comes from: if both players pick different studied maps,
            // the system randomly picks one of the remaining (which includes the third studied map)
            // Actually, let's reconsider the probability calculation...

            // Let's think more carefully:
            // We have 3 maps shown: let's say k of them are studied (k=1,2,3)
            // For each player, they pick one map to discard
            // The game is played on a map that neither player discarded

            // For a studied map to be played, at least one player must NOT discard it
            // This happens when:
            // - Both players discard non-studied maps (if available)
            // - Or one player discards a non-studied map and the other discards a different map

            // Let's use direct probability calculation instead of counting

            // Probability that a specific studied map is selected
            // = P(it's in the 3 shown) * P(both players don't discard it | it's shown)

            // P(it's in the 3 shown) = C(n-1, 2) / C(n, 3) = 3/n

            // Given it's shown, what's P(both players don't discard it)?
            // Each player randomly picks one of 3 maps to discard
            // P(a specific player doesn't discard it) = 2/3
            // P(both don't discard it) = 4/9
            // But if both discard the same other map, the system picks randomly among remaining 2
            // So if both don't discard our map, it survives with probability 1/2 or 1 depending on their choices

            // Let's enumerate all possibilities for 2 players choosing among 3 maps {A, B, C} where A is studied
            // Each player picks one to discard (3 choices each = 9 total)
            // A survives if neither discards A
            // Player 1 discards B, Player 2 discards B -> system picks randomly from {A,C} -> A survives with 1/2
            // Player 1 discards B, Player 2 discards C -> system picks randomly from {A} -> A survives with 1
            // Player 1 discards B, Player 2 discards A -> A doesn't survive
            // ... etc

            // Actually, simpler: A survives if at least one player doesn't discard A
            // P(A survives | A is shown) = 1 - P(both discard A) = 1 - (1/3)*(1/3) = 8/9

            // But wait, that's not right either because if both discard A, then the system picks randomly from the remaining 2
            // So A doesn't survive if both discard A, which happens with probability (1/3)*(1/3) = 1/9
            // So P(A survives | A is shown) = 8/9

            // Therefore, for each studied map, P(it's selected) = (3/n) * (8/9) = 8/(3n)
            // But this counts each game only once, and we want P(at least one studied map is selected)

            // This approach is getting complicated. Let's go back to the original formula and fix it.

            // Original formula seems to be trying to count cases based on how many studied maps are in the 3 shown
            // Let's re-derive:
            // Let i = number of studied maps
            // Case 1: 3 studied maps shown (C(i,3) ways)
            //   Each player picks one to discard. For a studied map to be played, at least one player must not discard it.
            //   Since all 3 are studied, if both players discard different maps, the third one is played.
            //   If both discard the same map, one of the other two is randomly selected.
            //   Probability that a studied map is played = 1 (since all are studied, any played map is studied)

            // Case 2: 2 studied maps shown (C(i,2) * C(n-i,1) ways)
            //   Let the maps be A(studied), B(studied), C(not studied)
            //   Players pick one to discard. For a studied map to be played:
            //   - If both discard C, then system picks randomly from {A,B} -> studied map played
            //   - If one discards A and one discards B, system picks C -> not studied
            //   - If one discards A and one discards C, system picks B -> studied
            //   - If one discards B and one discards C, system picks A -> studied
            //   Let's count: 9 total combinations
            //   (A,A): system picks from {B,C} -> 1/2 chance studied
            //   (A,B): system picks C -> 0 chance
            //   (A,C): system picks B -> 1 chance
            //   (B,A): system picks C -> 0 chance
            //   (B,B): system picks from {A,C} -> 1/2 chance studied
            //   (B,C): system picks A -> 1 chance
            //   (C,A): system picks B -> 1 chance
            //   (C,B): system picks A -> 1 chance
            //   (C,C): system picks from {A,B} -> 1 chance (since both are studied)
            //   Total probability = (1/2 + 0 + 1 + 0 + 1/2 + 1 + 1 + 1 + 1) / 9 = 7/9

            // Case 3: 1 studied map shown (C(i,1) * C(n-i,2) ways)
            //   Maps: A(studied), B,C(not studied)
            //   For A to be played, neither player can discard A
            //   P(both don't discard A) = (2/3)*(2/3) = 4/9
            //   But if both discard the same non-studied map, system picks randomly from remaining 2
            //   Let's enumerate:
            //   (A,A): system picks from {B,C} -> 0 chance (neither is studied)
            //   (A,B): system picks C -> 0 chance
            //   (A,C): system picks B -> 0 chance
            //   (B,A): system picks C -> 0 chance
            //   (B,B): system picks from {A,C} -> 1/2 chance
            //   (B,C): system picks A -> 1 chance
            //   (C,A): system picks B -> 0 chance
            //   (C,B): system picks A -> 1 chance
            //   (C,C): system picks from {A,B} -> 1/2 chance
            //   Total = (0+0+0+0+1/2+1+0+1+1/2)/9 = 3/9 = 1/3

            // Case 4: 0 studied maps shown -> 0 probability

            // So overall probability:
            // P = C(i,3)/C(n,3) * 1 + C(i,2)*C(n-i,1)/C(n,3) * (7/9) + C(i,1)*C(n-i,2)/C(n,3) * (1/3)

            long c3 = (long)studied * (studied-1) * (studied-2);
            long c2_1 = (long)studied * (studied-1) * (total - studied) * 3; // C(i,2)*C(n-i,1)*6? No...

            // Actually C(i,2) = i*(i-1)/2, C(n-i,1) = n-i
            // So C(i,2)*C(n-i,1) = i*(i-1)*(n-i)/2

            // Let me rewrite using the original formula structure but with correct coefficients

            // Original formula had:
            // prob = 1.5 * i * (n-i) * (n-i-1) / n / (n-1) / (n-2)
            //      + 3.0 * i * (i-1) * (n-i) / n / (n-1) / (n-2)
            //      + 1.0 * i * (i-1) * (i-2) / n / (n-1) / (n-2)

            // Let's check if this matches our derivation:
            // Term 1: 1.5 * i * (n-i) * (n-i-1) / (n*(n-1)*(n-2))
            //   This corresponds to case with 1 studied map: C(i,1)*C(n-i,2) = i * (n-i)*(n-i-1)/2
            //   Divided by C(n,3) = n*(n-1)*(n-2)/6
            //   So probability contribution = [i * (n-i)*(n-i-1)/2] / [n*(n-1)*(n-2)/6] * (1/3)
            //   = i * (n-i)*(n-i-1) * 6 / (2 * n*(n-1)*(n-2)) * (1/3)
            //   = i * (n-i)*(n-i-1) * 6 / (6 * n*(n-1)*(n-2))
            //   = i * (n-i)*(n-i-1) / (n*(n-1)*(n-2))
            //   But original has 1.5 * ... which is 3/2, not 1

            // Let me recalculate more carefully:
            // P(case 1: 3 studied) = C(i,3) / C(n,3) = [i*(i-1)*(i-2)/6] / [n*(n-1)*(n-2)/6] = i*(i-1)*(i-2) / [n*(n-1)*(n-2)]
            // Contribution to final probability = P(case 1) * 1

            // P(case 2: 2 studied) = C(i,2)*C(n-i,1) / C(n,3) = [i*(i-1)/2 * (n-i)] / [n*(n-1)*(n-2)/6] = 3*i*(i-1)*(n-i) / [n*(n-1)*(n-2)]
            // Contribution = P(case 2) * (7/9)

            // P(case 3: 1 studied) = C(i,1)*C(n-i,2) / C(n,3) = [i * (n-i)*(n-i-1)/2] / [n*(n-1)*(n-2)/6] = 3*i*(n-i)*(n-i-1) / [n*(n-1)*(n-2)]
            // Contribution = P(case 3) * (1/3)

            // So total probability = 
            //   i*(i-1)*(i-2) / D + 3*i*(i-1)*(n-i) * (7/9) / D + 3*i*(n-i)*(n-i-1) * (1/3) / D
            // where D = n*(n-1)*(n-2)
            // = [i*(i-1)*(i-2) + (7/3)*i*(i-1)*(n-i) + i*(n-i)*(n-i-1)] / D

            // Multiply numerator and denominator by 3 to eliminate fractions:
            // = [3*i*(i-1)*(i-2) + 7*i*(i-1)*(n-i) + 3*i*(n-i)*(n-i-1)] / (3*D)

            // Let's expand:
            // 3*i*(i-1)*(i-2) = 3*i*(i^2 - 3i + 2) = 3*i^3 - 9*i^2 + 6*i
            // 7*i*(i-1)*(n-i) = 7*i*[(i-1)*(n-i)] = 7*i*[i*n - i^2 - n + i] = 7*i^2*n - 7*i^3 - 7*i*n + 7*i^2
            // 3*i*(n-i)*(n-i-1) = 3*i*[(n-i)*(n-i-1)] = 3*i*[n^2 - n*i - n - n*i + i^2 + i] = 3*i*[n^2 - 2*n*i - n + i^2 + i]
            //                   = 3*i*n^2 - 6*i^2*n - 3*i*n + 3*i^3 + 3*i^2

            // This is getting too messy. Let me just compute directly using combinations.

            if (total < 3) return 0.0;

            long totalCombinations = (long)total * (total-1) * (total-2);

            long favorableCases = 0;

            // Case 1: 3 studied maps
            if (studied >= 3) {
                favorableCases += (long)studied * (studied-1) * (studied-2); // All studied, any outcome is good
            }

            // Case 2: 2 studied, 1 not studied
            if (studied >= 2 && (total - studied) >= 1) {
                // Number of ways to choose maps: studied*(studied-1)/2 * (total-studied)
                // But we need to count ordered selections for probability calculation
                // Actually, let's count ordered triples
                // Number of ordered triples with exactly 2 studied: 
                // Choose positions for studied maps: C(3,2) = 3 ways
                // Choose which studied maps: studied * (studied-1)
                // Choose which non-studied: (total-studied)
                // Total: 3 * studied * (studied-1) * (total-studied)
                // For each such triple, probability that a studied map is played = 7/9 as calculated
                // So contribution: 3 * studied * (studied-1) * (total-studied) * (7/9)
                favorableCases += 3 * studied * (studied-1) * (total-studied) * 7 / 9;
            }

            // Case 3: 1 studied, 2 not studied
            if (studied >= 1 && (total - studied) >= 2) {
                // Number of ordered triples: 3 * studied * (total-studied) * (total-studied-1)
                // Probability studied map is played = 1/3
                favorableCases += 3 * studied * (total-studied) * (total-studied-1) * 1 / 3;
            }

            return (double)favorableCases / totalCombinations;
        }

        // Let's use the simpler direct probability approach instead
        // For each studied map, compute probability it gets selected, then use inclusion-exclusion
        // But that's complex. Let me just use the original formula but with correct coefficients.

        // After re-examining the problem and original code, I think the original formula was trying to do:
        // prob = P(exactly 1 studied in 3) * P(studied played | 1 studied) +
        //        P(exactly 2 studied in 3) * P(studied played | 2 studied) +
        //        P(exactly 3 studied in 3) * P(studied played | 3 studied)

        // P(1 studied) = C(i,1)*C(n-i,2) / C(n,3) = [i * (n-i)*(n-i-1)/2] / [n*(n-1)*(n-2)/6] = 3*i*(n-i)*(n-i-1) / [n*(n-1)*(n-2)]
        // P(2 studied) = C(i,2)*C(n-i,1) / C(n,3) = [i*(i-1)/2 * (n-i)] / [n*(n-1)*(n-2)/6] = 3*i*(i-1)*(n-i) / [n*(n-1)*(n-2)]
        // P(3 studied) = C(i,3) / C(n,3) = i*(i-1)*(i-2) / [n*(n-1)*(n-2)]

        // P(studied played | 1 studied) = 1/3 (as calculated)
        // P(studied played | 2 studied) = 7/9 (as calculated)
        // P(studied played | 3 studied) = 1

        // So:
        // prob = 3*i*(n-i)*(n-i-1) / D * 1/3 + 3*i*(i-1)*(n-i) / D * 7/9 + i*(i-1)*(i-2) / D * 1
        // where D = n*(n-1)*(n-2)
        // = i*(n-i)*(n-i-1) / D + 7*i*(i-1)*(n-i) / (3*D) + i*(i-1)*(i-2) / D

        // Multiply numerator and denominator by 3:
        // = [3*i*(n-i)*(n-i-1) + 7*i*(i-1)*(n-i) + 3*i*(i-1)*(i-2)] / (3*D)

        // Let's simplify:
        // = i*(n-i)*(n-i-1) / D + 7*i*(i-1)*(n-i) / (3*D) + i*(i-1)*(i-2) / D

        // The original code had:
        // prob = 1.5 * i * (n-i) * (n-i-1) / n / (n-1) / (n-2)
        //      + 3.0 * i * (i-1) * (n-i) / n / (n-1) / (n-2)
        //      + 1.0 * i * (i-1) * (i-2) / n / (n-1) / (n-2)

        // So original coefficients were 1.5, 3.0, 1.0 instead of 1, 7/3≈2.333, 1

        // Let me check with a simple example: n=3, i=1
        // P = 1*(3-1)*(3-1-1)/D + 7*1*0*(3-1)/(3*D) + 1*0*(-1)/D = 1*2*1/D = 2/D
        // D = 3*2*1 = 6, so P = 2/6 = 1/3 ✓

        // With original formula: 1.5*1*2*1/6 + 3*1*0*2/6 + 1*1*0*(-1)/6 = 3/6 = 0.5 ✗

        // So the original formula is wrong. Let me fix it.

        // Correct formula:
        // prob = i*(n-i)*(n-i-1) / (n*(n-1)*(n-2)) 
        //      + 7*i*(i-1)*(n-i) / (3*n*(n-1)*(n-2))
        //      + i*(i-1)*(i-2) / (n*(n-1)*(n-2))

        // To avoid floating point precision issues, let's compute as:
        // prob = [3*i*(n-i)*(n-i-1) + 7*i*(i-1)*(n-i) + 3*i*(i-1)*(i-2)] / (3*n*(n-1)*(n-2))

        long numerator = 0;
        if (studied >= 1 && (total - studied) >= 2) {
            numerator += 3L * studied * (total - studied) * (total - studied - 1);
        }
        if (studied >= 2 && (total - studied) >= 1) {
            numerator += 7L * studied * (studied - 1) * (total - studied);
        }
        if (studied >= 3) {
            numerator += 3L * studied * (studied - 1) * (studied - 2);
        }

        long denominator = 3L * total * (total - 1) * (total - 2);

        return (double)numerator / denominator;
    }

    static class FastScanner {
        public BufferedReader reader;
        public StringTokenizer tokenizer;
        public FastScanner() {
            reader = new BufferedReader(new InputStreamReader(System.in), 32768);
            tokenizer = null;
        }
        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }
        public int nextInt() {
            return Integer.parseInt(next());
        }
        public long nextLong() {
            return Long.parseLong(next());
        }
        public double nextDouble() {
            return Double.parseDouble(next());
        }
        public String nextLine() {
            try {
                return reader.readLine();
            } catch(IOException e) {
                throw new RuntimeException(e);
            }
        }
    }
}
